---
--- 空花2.0生态构造体系统管控的AI 寻路状态脚本
--- Generated by EmmyLua(https://github.com/EmmyLua)
--- Created by Administrator.
--- DateTime: 2026/3/15 21:17
---

local EFindPathState = {
    None = 0,
    --- 在路上
    InPath = 1,
    --- 遭遇指挥官
    MeetCommander = 2,
    --- 路线跳转
    SkipPath = 3,
}

local XLevelNpcState = require("Common/StateMachine/State/XLevelNpcState")

---@class XEcologyFindCombinePathState: XLevelNpcState @生态AI寻路状态
---@field StateConfig XEcologyCharAIStateConfig
---@field CurFindPathState number 寻路状态, EFindPathState
---@field EnterState number 本次寻路进入时上层AI状态
---@field TargetState number 本次寻路目标上层AI状态
---@field CheckDistance number 目标点到达检查精度, 默认为1
---@field StartPos Vector3 启始点
---@field TargetPos Vector3 目标点
---@field Path Vector3[] 寻路路径
---@field _curPathPointIndex number 当前所处路径点索引
---@field _curTargetPathPoint Vector3 当前目标路径点
---@field _pathPointCount number 路径点数量
---@field _isMove boolean 是否在移动
local XEcologyFindCombinePathState = XClass(XLevelNpcState, "XEcologyFindCombinePathState")

function XEcologyFindCombinePathState:Ctor()
    self.Enable = false
    self.CurFindPathState = EFindPathState.None
end

---时序比OnStateEnter晚
function XEcologyFindCombinePathState:InitPath(enterState, targetState, checkDistance)
    self.EnterState = enterState
    self.TargetState = targetState
    if checkDistance ~= nil and checkDistance > 0 then
        self.CheckDistance = checkDistance
    else
        self.CheckDistance = 1
    end
    
    self:InitMoveParams()
    
    self._proxy:SetBBInt(XVarDomain.Npc, self._uuid, EEcologySaveKey.FindPathStartStateEnum, self.EnterState)
    self._proxy:SetBBInt(XVarDomain.Npc, self._uuid, EEcologySaveKey.FindPathTargetStateEnum, self.TargetState)
    --local haveSavePathIndex, findPathTargetIndex = self._proxy:TryGetBBInt(XVarDomain.Npc, self._uuid, EEcologySaveKey.FindPathCuePathIndex)
    --if haveSavePathIndex then
    --    self._curPathPointIndex = findPathTargetIndex
    --end
end

--region 基础生命周期
---@overload
function XEcologyFindCombinePathState:OnStateEnter(lastStateEnum)
    if self.StateConfig == nil then
        XScriptTool.EcologyError(self, "生态AI没有初始化数据")
        return
    end
    self._proxy:OnEcologyConstructCmpChangeState(self._placeId, self.StateConfig.StateEnum)
    
    self:UpdateOptionActive()
    self:RegisterWorldEvent()
end

---@overload
function XEcologyFindCombinePathState:OnStateLeave(nextStateEnum)
    if self.StateConfig == nil then
        return
    end
    
    self:UnRegisterWorldEvent()
    self:ChangeFindPathState(EFindPathState.None)
end

---@overload
function XEcologyFindCombinePathState:OnStateUpdate(dt)
    if self.StateConfig == nil then
        return
    end
    if self:CheckIsState(EFindPathState.None) then
        self:ChangeFindPathState(EFindPathState.InPath)
    end
    self:UpdatePathStateChange(dt)
end
--endregion

--region 事件响应
---@private
function XEcologyFindCombinePathState:RegisterWorldEvent()
    for _, event in pairs(self.StateConfig.RegisterWorldEventList) do
        self._proxy:RegisterEvent(event)
    end
end

---@private
function XEcologyFindCombinePathState:UnRegisterWorldEvent()
    for _, event in pairs(self.StateConfig.RegisterWorldEventList) do
        self._proxy:UnregisterEvent(event)
    end
end

---@overload
function XEcologyFindCombinePathState:HandleEvent(eventType, eventArgs)
    if self.StateConfig == nil then
        return
    end
    if eventType == EWorldEvent.ActorTrigger then
        self:OnActorTrigger(eventArgs)
    elseif eventType == EWorldEvent.NpcInteractStart then
        self:OnNpcInteractStart(eventArgs)
    end
end

function XEcologyFindCombinePathState:OnActorTrigger(eventArgs)
    -- 不是定义触发的TriggerId不执行逻辑
    if eventArgs.TriggerId ~= self.StateConfig.TriggerId or self._uuid ~= eventArgs.TriggerHolderUUID then
        return
    end

    if eventArgs.TriggerState == ETriggerState.Enter and self._proxy:IsPlayerNpc(eventArgs.EnteredActorUUID) then
        -- 剧情中不触发遇见指挥官
        if self._proxy:HasRunningDrama() then
            return
        end
        self:ChangeFindPathState(EFindPathState.MeetCommander)
    end
end

function XEcologyFindCombinePathState:OnNpcInteractStart(eventArgs)
    -- 被交互的不是自己不走逻辑
    if eventArgs.TargetId ~= self._uuid then
        return
    end
    if self.StateConfig.PathBubbleName then
        self._proxy:StopDramaBubble(ETargetActorType.Npc, self._uuid)
    end
    self:StopMove()
end

function XEcologyFindCombinePathState:OnLogPath()
    XScriptTool.EcologyError(self, "当前路径为第"..self._curCombineIndex.."条路径, 本次寻路所有路径:", self._combinePathList)
    XScriptTool.EcologyError(self, "当前路径为:", self.Path)
    XScriptTool.EcologyError(self, "当前为第"..self._curPathPointIndex.."个路径点", self._curTargetPathPoint)
end
--endregion

--region 基础逻辑 - 移动
function XEcologyFindCombinePathState:InitMoveParams()
    -- 是否在移动
    self._isMove = false

    -- 网格寻路
    self.OpenNavigateFindPath = self.StateConfig.FindPathConfig.OpenNavigateFindPath
    -- 重寻路间隔
    self.RecheckFindPathTime = self.StateConfig.FindPathConfig.RecheckFindPathTime or 4
    -- 重寻路间隔
    self._recheckFindPathTime = self.RecheckFindPathTime
    
    -- 路径相关
    self.Path = nil
    self.StartPos = nil
    self.TargetPos = nil
    self._curPathPointIndex = 0
    self._curTargetPathPoint = nil
    self._pathPointCount = 0
    
    -- 组合路径（一条路线分两端, 常见于上下楼）
    self._combinePathList = {}
    -- 当前组合路径
    self._curCombineIndex = 1
    local pathData = self._proxy:GetEcologyConstructStateRouteData(self._uuid, self.EnterState, self.TargetState)
    if not pathData then
        return
    end
    for i = 0, pathData.Count-1 do
        local path = {}
        -- 手动添加起点 确保能切实走到
        if i == 0 then
            table.insert(path, self._proxy:GetEcologyConstructStateInitPos(self._uuid, self.EnterState))
        end
        for j = 0, pathData[i].Count-1 do
            table.insert(path, pathData[i][j])
        end
        -- 手动添加终点 确保能切实走到
        if i == pathData.Count-1 then
            table.insert(path, self._proxy:GetEcologyConstructStateInitPos(self._uuid, self.TargetState))
        end
        table.insert(self._combinePathList, path)
    end
    
    self:RefreshCurPath(self._curCombineIndex)
end

function XEcologyFindCombinePathState:StartMove()
    if not self.Path then
        return
    end
    
    self._isMove = true
    self._curTargetPathPoint = self.Path[self._curPathPointIndex]
    if self.OpenNavigateFindPath then
        self._proxy:NpcNavigateTo(self._uuid, self._curTargetPathPoint, ENpcMoveType.Walk)
    else
        self._proxy:NpcMoveTo(self._uuid, self._curTargetPathPoint, ENpcMoveType.Walk)
    end
    self._recheckFindPathTime = self.RecheckFindPathTime
end

function XEcologyFindCombinePathState:StopMove()
    self._isMove = false
    self._proxy:NpcStopMove(self._uuid)
end

function XEcologyFindCombinePathState:RefreshCurPath(combineListIndex)
    if combineListIndex <= 0 then
        return
    end
    local combineListCount = #self._combinePathList
    if combineListIndex > combineListCount then
        return
    end
    -- 没有路径配置 强行塞终点和起点
    if combineListCount == 0 then
        self.Path = {}
        table.insert(self.Path, self._proxy:GetEcologyConstructStateInitPos(self._uuid, self.EnterState))
        table.insert(self.Path, self._proxy:GetEcologyConstructStateInitPos(self._uuid, self.TargetState))
    else
        self.Path = self._combinePathList[combineListIndex]
    end
    
    self._pathPointCount = #self.Path
    self.StartPos = self.Path[1]
    self.TargetPos = self.Path[self._pathPointCount]
    self._curPathPointIndex = 1
    if self._pathPointCount == 0 or not self.Path then
        XScriptTool.EcologyError(self, "[状态"..self.EnterState.."到状态"..self.TargetState.."]路径配置有问题, 没有明显路线, 请检查配置")
    end
end

---移动到下一个路近点
---@private
function XEcologyFindCombinePathState:MoveNext()
    self._curPathPointIndex = self._curPathPointIndex + 1
    if self._curPathPointIndex > self._pathPointCount then
        -- 到达路线终点时判断是否是组合路线
        if self._curCombineIndex < #self._combinePathList then
            self._curCombineIndex = self._curCombineIndex + 1
            self:ChangeFindPathState(EFindPathState.SkipPath)
            return
        else
            self._curPathPointIndex = self._pathPointCount
        end
    end

    self:OnMoveNext()
    self:StartMove()
    --XLog.Debug("[脚本: "..self._proxy.Id.."]寻路状态路径前往路径第:"..self._curPathPointIndex.."个路径点", self._curTargetPathPoint)
end

---@overload
function XEcologyFindCombinePathState:OnMoveNext()
    self._proxy:SetBBInt(XVarDomain.Npc, self._uuid, EEcologySaveKey.FindPathCuePathIndex, self._curPathPointIndex)
end
--endregion

--region 基础逻辑 - 交互控制
function XEcologyFindCombinePathState:UpdateOptionActive()
    self._proxy:SetNpcInteractOneOptionActive(self._placeId, self.StateConfig.ShowOptionId)
end
--endregion

--region 基础逻辑 - 气泡
function XEcologyFindCombinePathState:PlayMeetCommanderBubble()
    local bubbleName = self.StateConfig.FindPathConfig.MeetCommanderBubbleName
    if bubbleName then
        self._proxy:PlayDramaBubble(ETargetActorType.Npc, self._uuid, bubbleName)
    end
end

function XEcologyFindCombinePathState:StopMeetCommanderBubble()
    if self.StateConfig.FindPathConfig.MeetCommanderBubbleName then
        self._proxy:StopDramaBubble(ETargetActorType.Npc, self._uuid)
    end
end
--endregion

--region 寻路内状态逻辑
---@private
function XEcologyFindCombinePathState:CheckIsState(state)
    return self.CurFindPathState == state
end

---private
---@field state number 寻路状态, EFindPathState
function XEcologyFindCombinePathState:ChangeFindPathState(state)
    if self.CurFindPathState == state then
        return
    end
    local lastFindPathState = self.CurFindPathState
    self:OnFindPathStateExit(lastFindPathState, state)
    self.CurFindPathState = state
    self:OnFindPathStateEnter(lastFindPathState, state)
end

---private
---@field lastState number 上一个状态, EFindPathState
---@field targetState number 目标状态, EFindPathState
function XEcologyFindCombinePathState:OnFindPathStateEnter(lastState, targetState)
    if targetState == EFindPathState.InPath then
        self:OnEnterInPath(lastState, targetState)
    elseif targetState == EFindPathState.MeetCommander then
        self:OnEnterMeetCommander(lastState, targetState)
    elseif targetState == EFindPathState.SkipPath then
        self:OnEnterSkipPath(lastState, targetState)
    end
end

---private
---@field lastState number 上一个状态, EFindPathState
---@field targetState number 目标状态, EFindPathState
function XEcologyFindCombinePathState:OnFindPathStateExit(lastState, targetState)
    if lastState == EFindPathState.InPath then
        self:OnLeaveInPath(lastState, targetState)
    elseif lastState == EFindPathState.MeetCommander then
        self:OnLeaveMeetCommander(lastState, targetState)
    elseif lastState == EFindPathState.SkipPath then
        self:OnLeaveSkipPath(lastState, targetState)
    end
end

---private
function XEcologyFindCombinePathState:UpdatePathStateChange(dt)
    if self.CurFindPathState == EFindPathState.InPath then
        self:OnUpdateInPath(dt)
    elseif self.CurFindPathState == EFindPathState.MeetCommander then
        self:OnUpdateMeetCommander(dt)
    elseif self.CurFindPathState == EFindPathState.SkipPath then
        self:OnUpdateSkipPath(dt)
    end
end
--endregion

--region 状态 - 在路上
function XEcologyFindCombinePathState:OnEnterInPath(lastState, targetState)
    self:StartMove()
end

function XEcologyFindCombinePathState:OnUpdateInPath(dt)
    if not self.Path or self._pathPointCount == 0 then
        return
    end

    if self._isMove then
        self._recheckFindPathTime = self._recheckFindPathTime - dt
        if self._recheckFindPathTime <= 0 then
            self:StartMove()
        end
    end
    
    if self._proxy:CheckNpcDistanceWithPos(self._uuid, self._curTargetPathPoint.x, self._curTargetPathPoint.y, self._curTargetPathPoint.z, self.CheckDistance) then
        self:MoveNext()
    end
end

function XEcologyFindCombinePathState:OnLeaveInPath(lastState, targetState)
    self:StopMove()
end
--endregion

--region 状态 - 遭遇指挥官
---private
function XEcologyFindCombinePathState:InitMeetCommanderParams()
    -- 遭遇指挥官停留时间
    self._meetTime = 5
    -- 当前停留时间
    self._curMeetTime = self._meetTime
end

function XEcologyFindCombinePathState:OnEnterMeetCommander(lastState, targetState)
    self:InitMeetCommanderParams()

    self:PlayMeetCommanderBubble()
    self._proxy:EnableNpcLookAt(self._uuid, self._proxy:GetLocalPlayerNpcId())
    self._proxy:TurnNpc(self._uuid,self._proxy:GetLocalPlayerNpcId(),"Drama_Stand_01")
end

function XEcologyFindCombinePathState:OnUpdateMeetCommander(dt)
    if self._curMeetTime <= 0 then
        self:ChangeFindPathState(EFindPathState.InPath)
        return
    end
    
    -- 停下时在剧情/交互中则不计时离开
    if self._proxy:HasRunningDrama() or self._proxy:CheckNpcIsInInteract(self._placeId) then
        return
    end
    
    self._curMeetTime = self._curMeetTime - dt
end

function XEcologyFindCombinePathState:OnLeaveMeetCommander(lastState, targetState)
    self._proxy:DisableNpcLookAt(self._uuid, self._proxy:GetLocalPlayerNpcId())
    self:StopMeetCommanderBubble()
end
--endregion

--region 状态 - 路线跳转
function XEcologyFindCombinePathState:OnEnterSkipPath(lastState, targetState)
    self._skipIn = true
    self._skipPathTime = self.StateConfig.FindPathConfig.CombineRouteFadeOutTime or 1
    self:RefreshCurPath(self._curCombineIndex)
    self._proxy:SetNpcFade(self._uuid, false, self._skipPathTime)
end

function XEcologyFindCombinePathState:OnUpdateSkipPath(dt)
    if self._skipPathTime <= 0 then
        if not self._skipIn then
            self:ChangeFindPathState(EFindPathState.InPath)
        else
            self._skipIn = false
            self._proxy:SetNpcPosition(self._uuid, self.StartPos, true)
            self._skipPathTime = self.StateConfig.FindPathConfig.CombineRouteFadeInTime or 1
            self._proxy:SetNpcFade(self._uuid, true, self._skipPathTime)
        end
    end
    self._skipPathTime = self._skipPathTime - dt
end

function XEcologyFindCombinePathState:OnLeaveSkipPath(lastState, targetState)
end
--endregion

return XEcologyFindCombinePathState